-- Bootstrap schema is also generated by SQLAlchemy Base.metadata.create_all.
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(120) UNIQUE NOT NULL,role VARCHAR(20) NOT NULL,password_hash VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS processes(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,temperature FLOAT NOT NULL,dwell FLOAT NOT NULL,pressure FLOAT NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS samples(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,process_id INTEGER NOT NULL REFERENCES processes(id),lot VARCHAR(60) NOT NULL,force FLOAT NOT NULL,flagged BOOLEAN NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessments(id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,lot VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL,snapshot JSON NOT NULL,result JSON,error TEXT NOT NULL,recommendation TEXT NOT NULL,selected_process_id INTEGER REFERENCES processes(id),approved BOOLEAN NOT NULL,approved_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id SERIAL PRIMARY KEY,actor VARCHAR(120) NOT NULL,action VARCHAR(200) NOT NULL,status INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL);
